\begin{definition}\label{def:brownianQuadraticVariation}
  \uses{def:quadraticVariation, lem:isLocalMartingale_brownian, lem:isCadlag_brownian, lem:brownianNaturalFiltration_approximable}
  \lean{ProbabilityTheory.brownianQuadraticVariation}
  \leanok
The quadratic variation process attached to the canonical Brownian motion is
\[
  \langle B\rangle := \operatorname{quadraticVariation}(B).
\]
Formally this is an application of the generic quadratic-variation definition,
so the Brownian filtration must satisfy the usual hypotheses required by the
normalized Doob--Meyer choice layer.  Approximability is supplied by
Lemma~\ref{lem:brownianNaturalFiltration_approximable}; completeness and
right-continuity are genuine usual-condition obligations for the filtration
used in the formal statement, not consequences to assert for the raw natural
filtration without proof.
\end{definition}

\begin{lemma}\label{lem:martingale_brownian_sq_sub_time}
  \uses{def:brownianNaturalFiltration}
  \lean{ProbabilityTheory.martingale_brownian_sq_sub_time}
  \leanok
The process \(B_t^2-t\) is a martingale with respect to the natural Brownian filtration.
\end{lemma}

\begin{proof}


\leanok
It is adapted because \(B_t\) is \(\mathcal F^B_t\)-measurable and \(t\) is
deterministic.  It is integrable because \(B_t\) is Gaussian with finite second
moment.

Fix \(s\le t\) and write \(\Delta_{s,t}=B_t-B_s\).  Then
\[
  B_t^2-t
  = B_s^2-s + 2B_s\Delta_{s,t}
    +\bigl(\Delta_{s,t}^2-(t-s)\bigr).
\]
The increment \(\Delta_{s,t}\) is independent of \(\mathcal F^B_s\), centered,
and has law \(N(0,t-s)\).  Therefore
\[
  \mathbb E[\Delta_{s,t}\mid\mathcal F^B_s]=0,
  \qquad
  \mathbb E[\Delta_{s,t}^2\mid\mathcal F^B_s]=t-s.
\]
Since \(B_s\) is \(\mathcal F^B_s\)-measurable, the mixed term has conditional
expectation
\[
  \mathbb E[B_s\Delta_{s,t}\mid\mathcal F^B_s]
  = B_s\,\mathbb E[\Delta_{s,t}\mid\mathcal F^B_s]=0.
\]
Taking conditional expectations in the displayed expansion gives
\[
  \mathbb E[B_t^2-t\mid\mathcal F^B_s]=B_s^2-s,
\]
which is the martingale property.
\end{proof}

\begin{lemma}\label{lem:isCadlag_brownian_sq_sub_time}
  \uses{def:brownian, lem:isCadlag_brownian}
  \lean{ProbabilityTheory.isCadlag_brownian_sq_sub_time}
  \leanok
The process \(t\mapsto B_t^2-t\) has càdlàg paths.
\end{lemma}

\begin{proof}

\leanok
For each sample point \(\omega\), the Brownian path \(t\mapsto B_t(\omega)\)
is continuous.  Squaring and subtracting the continuous deterministic map
\(t\mapsto t\) preserves continuity, hence the resulting path is càdlàg.
\end{proof}

\begin{definition}\label{def:brownianDeterministicTime}
  \lean{ProbabilityTheory.brownianDeterministicTime}
  \leanok
The deterministic time process is
\[
  T_t(\omega)=(t:\mathbb R).
\]
\end{definition}

\begin{lemma}\label{lem:brownianDeterministicTime_predictable}
  \uses{def:brownianNaturalFiltration, def:brownianDeterministicTime}
  \lean{ProbabilityTheory.isStronglyPredictable_brownianDeterministicTime}
  \leanok
The deterministic time process is strongly predictable with respect to the
Brownian natural filtration.
\end{lemma}

\begin{proof}

\leanok
The process is strongly adapted because, for every \(t\), the random variable
\(\omega\mapsto t\) is constant.  Its paths are left-continuous, since
\(t\mapsto (t:\mathbb R)\) is continuous on \(\mathbb R_{\ge 0}\).  The
project's predictable-process API says that a left-continuous strongly adapted
process on the nonnegative real time line is strongly predictable, so the
claim follows.
\end{proof}

\begin{lemma}\label{lem:brownianDeterministicTime_progressive}
  \uses{def:brownianDeterministicTime, lem:Adapted.isStronglyProgressive_of_rightContinuous}
  \lean{ProbabilityTheory.isStronglyProgressive_brownianDeterministicTime}
  \leanok
The deterministic time process is strongly progressive with respect to the
Brownian natural filtration.
\end{lemma}

\begin{proof}

\leanok
The process is strongly adapted because each fixed-time random variable is
constant.  Its paths are right-continuous because
\(t\mapsto(t:\mathbb R)\) is continuous.  Apply the project's
right-continuous strongly adapted process criterion for strong
progressiveness.
\end{proof}

\begin{lemma}\label{lem:brownianDeterministicTime_cadlag}
  \uses{def:brownianDeterministicTime}
  \lean{ProbabilityTheory.isCadlag_brownianDeterministicTime}
  \leanok
The deterministic time process has càdlàg paths.
\end{lemma}

\begin{proof}

\leanok
Every path is the continuous map \(t\mapsto (t:\mathbb R)\), and every
continuous path is càdlàg.
\end{proof}

\begin{lemma}\label{lem:brownianDeterministicTime_hasLocallyIntegrableSup}
  \uses{def:brownianDeterministicTime}
  \lean{ProbabilityTheory.hasLocallyIntegrableSup_brownianDeterministicTime}
  \leanok
The deterministic time process has locally integrable running supremum.
\end{lemma}

\begin{proof}

\leanok
First prove the global running-sup condition.  For fixed \(t\) and every
\(\omega\),
\[
  \sup_{s\le t} \|T_s(\omega)\| = \sup_{s\le t} s = t,
\]
because \(s\mapsto s\) is monotone and nonnegative on \(\mathbb R_{\ge 0}\).
Thus the running-sup random variable is the constant \(t\), hence is strongly
measurable and integrable under the finite Brownian measure.  The product
strong measurability of \((t,\omega)\mapsto\sup_{s\le t}\|T_s(\omega)\|\)
comes from the measurable map \(t\mapsto t\).  The local version follows by
using the constant-\(\top\) localizing sequence, i.e. by viewing a global
`HasIntegrableSup` proof as a local one.
\end{proof}

\begin{lemma}\label{lem:brownianDeterministicTime_monotone}
  \uses{def:brownianDeterministicTime}
  \lean{ProbabilityTheory.monotone_brownianDeterministicTime}
  \leanok
The deterministic time process is pathwise monotone.
\end{lemma}

\begin{proof}

\leanok
If \(s\le t\) in \(\mathbb R_{\ge 0}\), then \((s:\mathbb R)\le(t:\mathbb R)\).
\end{proof}

\begin{lemma}\label{lem:brownianDeterministicTime_bot_eq_zero}
  \uses{def:brownianDeterministicTime}
  \lean{ProbabilityTheory.brownianDeterministicTime_bot_eq_zero}
  \leanok
The deterministic time process starts from zero:
\[
  T_0(\omega)=0.
\]
\end{lemma}

\begin{proof}

\leanok
This is immediate from the definition and the fact that the bottom element of
\(\mathbb R_{\ge 0}\) is \(0\).
\end{proof}

\begin{lemma}\label{lem:quadraticVariation_brownian}
  \uses{def:brownianQuadraticVariation, lem:martingale_brownian_sq_sub_time, lem:isCadlag_brownian_sq_sub_time, lem:brownianDeterministicTime_predictable, lem:brownianDeterministicTime_progressive, lem:brownianDeterministicTime_cadlag, lem:brownianDeterministicTime_hasLocallyIntegrableSup, lem:brownianDeterministicTime_monotone, lem:brownianDeterministicTime_bot_eq_zero, lem:predictablePart_eq_of_normalized_decomposition}
  \lean{ProbabilityTheory.quadraticVariation_brownian}
  \leanok
Let \(B\) be the canonical Brownian motion. Under the usual hypotheses used
to define the Brownian quadratic variation, its quadratic variation is
equal to the deterministic time process at every deterministic time: for every
\(t\in\mathbb R_{\ge 0}\),
\[
  \langle B\rangle_t = t
\]
almost surely.  Formally, the statement is
\[
  \texttt{brownianQuadraticVariation t =ᵐ[gaussianLimit] fun \_ => (t : ℝ)}.
\]
When the available equality notion is upgraded from fixed-time modification
to indistinguishability for càdlàg processes, this fixed-time statement
promotes to \(\mathbb P\)-almost sure equality of the whole paths.
\end{lemma}

\begin{proof}

\leanok
The candidate Doob--Meyer decomposition of \(B_t^2\) is
\[
  B_t^2 = (B_t^2-t) + t.
\]
By Lemma~\ref{lem:martingale_brownian_sq_sub_time}, the first summand is a
martingale, hence a local martingale, and by
Lemma~\ref{lem:isCadlag_brownian_sq_sub_time} it has càdlàg paths.  The second
summand is the deterministic time process \(T\).  The preceding deterministic
lemmas show that \(T\) is strongly predictable, strongly progressive, càdlàg,
has locally integrable running supremum, is nondecreasing pathwise, and starts
from zero.

The squared Brownian process used by the generic quadratic-variation
definition is \(X_t=\|B_t\|^2=B_t^2\).  The displayed identity is therefore a
normalized Doob--Meyer decomposition of \(X\), with martingale part
\(B_t^2-t\) and predictable part \(T_t=t\).  Applying the normalized
predictable-part comparison theorem identifies the choice-based predictable
part used in \(\operatorname{brownianQuadraticVariation}\) with \(T\) at the
fixed time \(t\), almost surely.

